INSERT INTO subsidy (id, raw_id, source, external_id, name, summary, org_name, category_raw, category, target_raw, benefit_raw, apply_method, apply_deadline_raw, apply_deadline_date, biz_start_date, biz_end_date, detail_url, min_age, max_age, income_pct_max, income_amt_min, income_amt_max, protection_status_required, min_years_after_end, max_years_after_end, target_household, exclusion_group, duplicate_of_subsidy_id, needs_manual_review, created_at) OVERRIDING SYSTEM VALUE VALUES (18, NULL, 'gov24', '461000000308', '자립준비청년(보호종료아동) 대학생활안정자금 지원', '보호종료 및 보호종료 5년 이내 아동 중 대학 진학시 대학생활안정자금을 지원합니다.', '충청남도 예산군', NULL, '주거자립', 'o 도내 양육시설, 공동생활가정, 가정위탁 보호종료아동(보호연장아동 포함) 및 보호종료 5년 이내 아동 중 대학진학자임과 동시에 주민등록상 도내 거주자', '2023년 대학진학자부터 적용 (지원조건) -「고등교육법」제2조에 따른 대학 진학자 - 「평생교육법」제32조 및 제33조에 따라 전문대학 또는 대학졸업자와 동등한 학력·학위가 인정되는 평생교육시설(사이버대학, 학정은행제) 진학자 (지원금액) 1인 200만원(일시금) (지원방법) 신청자 명의 계좌로 현금 지급', '방문신청', '등록금 납입일로부터 6개월 이내', NULL, NULL, NULL, 'https://www.gov.kr/portal/rcvfvrSvc/dtlEx/461000000308', NULL, NULL, NULL, NULL, NULL, '보호종료', NULL, 5, '{}', NULL, NULL, true, '2026-09-02 18:33:13.02405');
INSERT INTO subsidy (id, raw_id, source, external_id, name, summary, org_name, category_raw, category, target_raw, benefit_raw, apply_method, apply_deadline_raw, apply_deadline_date, biz_start_date, biz_end_date, detail_url, min_age, max_age, income_pct_max, income_amt_min, income_amt_max, protection_status_required, min_years_after_end, max_years_after_end, target_household, exclusion_group, duplicate_of_subsidy_id, needs_manual_review, created_at) OVERRIDING SYSTEM VALUE VALUES (19, NULL, 'gov24', '508000000565', '자립준비청년(보호종료아동) 자립수당 지급', '보호가 종료된 아동을 대상으로 본인 명의 계좌로 매월 50만원의 자립수당을 지원합니다.', '보건복지부', NULL, '주거자립', '○ 아동복지시설, 가정위탁 보호종료 아동 중 보호종료일을 기준으로 과거 2년 이상 연속하여 보호를 받은 자로서, 다음 사항 중 어느 하나에 해당하는 경우 - 만 18세 이후 만기 또는 연장 보호종료된 자로서 보호종료 5년 이내인 자(단, ''18.8월 이후 보호종료된 자) - 만 15세 이후 보호조치가 조기 종료된 자로서 만 18세가 된 때로부터 5년 이내인 자 (단, 아동복지법 시행(’24.2.9.)이후 만 18세가 된 자부터 적용) ※ 지원 불가: ① 보호 조기종료 후 원가정으로 복귀한 경우, ② 자립수당 신청 시 타 법령에 따라 자립수당 등을 지원받고 있는 경우', '매월 50만원의 자립수당 지원', '기타 온라인신청||방문신청', '상시신청', NULL, NULL, NULL, 'https://www.gov.kr/portal/rcvfvrSvc/dtlEx/508000000565', 15, 18, NULL, NULL, NULL, '보호종료', 0, 5, '{}', NULL, NULL, true, '2026-09-02 18:33:13.038896');
INSERT INTO subsidy (id, raw_id, source, external_id, name, summary, org_name, category_raw, category, target_raw, benefit_raw, apply_method, apply_deadline_raw, apply_deadline_date, biz_start_date, biz_end_date, detail_url, min_age, max_age, income_pct_max, income_amt_min, income_amt_max, protection_status_required, min_years_after_end, max_years_after_end, target_household, exclusion_group, duplicate_of_subsidy_id, needs_manual_review, created_at) OVERRIDING SYSTEM VALUE VALUES (20, NULL, 'gov24', '628000000780', '자립준비청년 자립정착금 지원', '자립준비청년 자립정착금 지원', '인천광역시', NULL, '생활안정', '○ 지원대상  - 만 15세 이후 아동복지시설(아동양육시설, 공동생활가정), 가정위탁 보호 조기 종료 된 아동    [단, 아동복지법(''24.2.9.)이후 만 18세가 된 사람부터 적용]  - 만 18세 이후 아동복지시설(아동양육시설, 공동생활가정), 가정위탁 보호 만기·연장보호종료 아동   ※ 지원제외 : 보호 조기 종료 이후 원가정으로 복귀한 경우', '보호종료 시 자립정착금 1,000만원 지급(인, 1회)', '방문신청', '상시신청', NULL, NULL, NULL, 'https://www.gov.kr/portal/rcvfvrSvc/dtlEx/628000000780', 15, NULL, NULL, NULL, NULL, '보호종료', NULL, NULL, '{}', NULL, NULL, true, '2026-09-02 18:33:15.927194');
INSERT INTO subsidy (id, raw_id, source, external_id, name, summary, org_name, category_raw, category, target_raw, benefit_raw, apply_method, apply_deadline_raw, apply_deadline_date, biz_start_date, biz_end_date, detail_url, min_age, max_age, income_pct_max, income_amt_min, income_amt_max, protection_status_required, min_years_after_end, max_years_after_end, target_household, exclusion_group, duplicate_of_subsidy_id, needs_manual_review, created_at) OVERRIDING SYSTEM VALUE VALUES (21, NULL, 'gov24', '629000000140', '자립준비청년자립정착금', '18세 이상의 가정위탁보호 종결아동에게 자립정착금 지원', '전남광주통합특별시', NULL, '주거자립', '○ 지원대상 : 18세 이상의 가정위탁보호 종결아동(연장보호종결아동 포함)  - 단, 아동의 대학교 조기입학 등 예외적인 사유로 만17세에 아동복지시설 혹은 가정위탁 보호가 종료되는 경우, 지자체 판단 하에 자립정착금 지원 가능', '○ 사업내용 : 만 18세 이상의 아동이 사회에서 자립하는 데 필요한 비용을 지원함으로써 자립 활성화에 기여 ○ 지원방법 : 자립정착금 지급 시 사용계획 필수 확인 및 아동명의의 계좌로 입금', '방문신청', '상시신청', NULL, NULL, NULL, 'https://www.gov.kr/portal/rcvfvrSvc/dtlEx/629000000140', 17, NULL, NULL, NULL, NULL, '보호종료', NULL, NULL, '{}', NULL, NULL, true, '2026-09-02 18:33:15.944042');
