INSERT INTO subsidy (id, raw_id, source, external_id, name, summary, org_name, category_raw, category, target_raw, benefit_raw, apply_method, apply_deadline_raw, apply_deadline_date, biz_start_date, biz_end_date, detail_url, min_age, max_age, income_pct_max, income_amt_min, income_amt_max, protection_status_required, min_years_after_end, max_years_after_end, target_household, exclusion_group, duplicate_of_subsidy_id, needs_manual_review, created_at) OVERRIDING SYSTEM VALUE VALUES (23, NULL, 'gov24', '641000000159', '자립준비청년 자립지원정착금 지원', '보호종료 5년 이내 자립준비청년에게 자립지원정착금을 지원합니다.', NULL, NULL, '생활안정', '○ 대상자    -  18세 이후 보호가 종료 된 아동복지시설* 및 가정위탁 보호종료아동(만기퇴소 또는 연장 보호종료 된 자)     * 아동양육시설, 아동일시보호시설, 아동보호치료시설, 공동생활가정, 학대피해아동쉼터     * 15세 이후 보호조치가 조기 종료된 자로서 18세가 된 때로부터 5년 이내인 경우 지원        (단, 아동복지법 시행(''24.2.9.)이후 만 18세가 된 자부터 적용)   - 도 내 시설 2년이상(보호기간 합산가능) 거주하며, 만기퇴소 직전 6개월이상은 양육시설, 공동생활가정, 위탁가정에서 생활 한자   ○ 지급방법 : 2차에 걸쳐 지급    - 1차 : 퇴소한 년도에 10백만원 지원    - 2차 : 다음연도에 5백만원 지원*  * 증빙서류 제출 지원내용: ○ 자립준비청년 자립지원정착금 지원   - ''20년 5백만원, 21년 10백만원, 22년 이후 15백만원(1차 10백만원, 2차 5백만원) 지원유형: 현금 사용자구분: 개인 상세조회URL: https://www.gov.kr/portal/rcvfvrSvc/dtlEx/641000000159 서비스분야: 생활안정 소관기관명: 경기도 소관기관유형: 광역시도 소관기관코드: 6410000 서비스목적요약: 보호종료 5년 이내 자립준비청년에게 자립지원정착금 지원 minAge: 18 maxAge: null incomePctMax: null incomeAmtMin: null incomeAmtMax: null protectionStatusRequired: 보호종료 minYearsAfterEnd: null maxYearsAfterEnd: 5 targetHousehold: [], benefits: [   {     "benefitName": "1차 자립지원정착금",     "amountKrw": 10000000,     "cycle": "일시금"   },   {     "benefitName": "2차 자립지원정착금",     "amountKrw": 5000000,     "cycle": "일시금"   } ], regions: [   {     "sidoCode": "6410000"   } ]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, '2026-09-02 18:33:21.015868');
